// Espelha scripts/coletar.py. Filtro aplicado SO em `name`: em `description`
// a medicao deu 47% de falso positivo em "dados" e 30% de falso negativo em
// "suporte".
const norm = (s) => (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

const NIVEL = ['estagio', 'estagiario', 'estagiaria', 'junior', 'jr', 'trainee'];
const AREA = ['desenvolvedor', 'desenvolvimento', 'software', 'backend', 'frontend',
  'fullstack', 'dados', 'data', 'python', 'java', 'javascript', 'automacao',
  'cloud', 'aws', 'engenheiro'];
const EXCLUIR = ['suporte', 'aprendiz', 'contabilidade', 'vendas', 'comercial',
  'telemarketing'];

// Fronteira de palavra: sem isso 'jr' casa dentro de outra palavra.
const bate = (titulo, termos) => termos.filter((t) => new RegExp('\\b' + t + '\\b').test(titulo));

const agora = Date.now();
const MAX_IDADE = 72 * 3600 * 1000;
const hoje = new Date().toISOString().slice(0, 10);
const saida = [];

for (const item of $input.all()) {
  const vagas = (item.json && item.json.data) || [];
  for (const v of vagas) {
    const titulo = norm(v.name);

    // Exclusao tem precedencia sobre area.
    if (bate(titulo, EXCLUIR).length > 0) continue;

    const ehEstagio = v.type === 'vacancy_type_internship';
    // Para internship o proprio type ja provou o nivel.
    if (!ehEstagio && bate(titulo, NIVEL).length === 0) continue;

    const areas = bate(titulo, AREA);
    if (areas.length === 0) continue;

    // publishedDate vem em dois formatos; sem o Z o JS assume horario local.
    let iso = v.publishedDate;
    if (!iso) continue;
    if (/^\d{4}-\d{2}-\d{2}$/.test(iso)) iso = iso + 'T00:00:00Z';
    const publicada = Date.parse(iso);
    if (!publicada) continue;
    const idade = agora - publicada;
    if (idade > MAX_IDADE) continue;

    const prazo = v.applicationDeadline || '';
    if (prazo && prazo < hoje) continue;

    const remoto = Boolean(v.isRemoteWork) || v.workplaceType === 'remote';
    let score = 0;
    const motivos = [];
    if (remoto) { score += 40; motivos.push('remoto'); }
    if (ehEstagio) { score += 30; motivos.push('internship'); }
    score += 20; motivos.push(areas[0]);
    if (idade < 6 * 3600 * 1000) { score += 10; motivos.push('recente'); }

    saida.push({ json: {
      id_externo: String(v.id),
      titulo: String(v.name || '').trim(),
      empresa: v.careerPageName || '',
      url: v.jobUrl || '',
      tipo: v.type || '',
      workplace_type: v.workplaceType || '',
      cidade: v.city || '',
      remoto: remoto,
      publicada_em: new Date(publicada).toISOString(),
      prazo: prazo,
      score: score,
      motivo: motivos.join('; '),
    } });
  }
}

return saida;

// Monta uma mensagem so, e a lista de ids que sera carimbada depois do envio.
const itens = $input.all().filter((i) => i.json && i.json.id_externo);
if (itens.length === 0) return [];

const destino = itens[0].json.destino || '';
if (!destino) {
  throw new Error('config.whatsapp_destino nao definido. Rode o INSERT documentado em db/01-schema.sql');
}

const linhas = ['*' + itens.length + ' vaga(s) nova(s)*', ''];
for (const item of itens) {
  const v = item.json;
  let local = v.workplace_type || '?';
  if (v.cidade) local = local + ' \u00b7 ' + v.cidade;
  // O WhatsApp so fecha o negrito com o * colado a caractere nao-branco.
  const titulo = String(v.titulo || '').trim();
  linhas.push(titulo ? '*' + titulo + '*' : '(sem titulo)');
  linhas.push((v.empresa || '') + ' \u00b7 ' + local);
  if (v.prazo) linhas.push('prazo: ' + String(v.prazo).slice(0, 10));
  linhas.push(v.url || '');
  linhas.push('');
}

return [{ json: {
  destino: destino,
  texto: linhas.join('\n').trim(),
  ids: itens.map((i) => i.json.id_externo).join(','),
} }];

